import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while True:
        if proc.poll() is not None:
            break
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        try:
            cpu_usage += p.cpu_percent(interval=0.1)
            memory_usage += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist or is not a file.")
    proc = subprocess.Popen([script_path], shell=True)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    prev_mem = 0
    while True:
        try:
            if not p.is_running():
                break
            status = p.status()
            if status == psutil.STATUS_ZOMBIE:
                break
            cpu = p.cpu_percent(interval=0)
            cpu_usage += cpu
            mem = p.memory_info().rss
            if mem > prev_mem:
                mem_usage += (mem - prev_mem)
            prev_mem = mem
            elapsed = time.time() - start_time
            if elapsed > timeout:
                proc.terminate()
                break
            time.sleep(0.1)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
    if proc.poll() is None:
        proc.terminate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

