            if not p.is_running():
                break
            if p.status() == 'zombie':
                break
            cpu_usage += p.cpu_percent(interval=0.0)
            mem_usage += p.memory_info().rss
        except psutil.NoSuchProcess:
            break
        except psutil.ZombieProcess:
            break

        if time.time() - start_time >= timeout:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
            break

        time.sleep(0.1)

    if proc.poll() is None:
        proc.terminate()
        try:
            proc.wait(timeout=2)
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait()

    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

